#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

#define int long long
const int MOD1 = 998244353, MOD2 = 1000000007;
const int pow_arr[] = {1, 10, 100, 1000, 10000, 100000, 1000000};

int prefix_sum[7], total_answer, counter1, limit, counter2;
vector<int> digit_vectors[7];

void generate(int level, int val) {
    if (level == 7) return;
    digit_vectors[level].push_back((counter1 - val + MOD1) % MOD1);
    prefix_sum[level] += (counter1 - val + MOD1) % MOD1;
    counter1++;
    for (int d = 0; d <= 9; ++d) {
        generate(level + 1, val * 10 + d);
    }
}

bool is_in_range(int x) {
    return x * pow_arr[6] + 999999 <= limit && x * pow_arr[6] * 10 > limit;
}

void search(int level, int current) {
    if (current > limit) return;
    if (is_in_range(current)) {
        for (int i = 0; i <= 6; ++i) {
            int p = ((counter2 + 1 - (current * pow_arr[i])) % MOD1 + MOD1) % MOD1;
            int pos = (int)(lower_bound(digit_vectors[i].begin(), digit_vectors[i].end(), MOD1 - p) - digit_vectors[i].begin());
            total_answer = (total_answer + (prefix_sum[i] + p * digit_vectors[i].size() - MOD1 * (digit_vectors[i].size() - pos))) % MOD2;
        }
        counter2 += counter1;
        return;
    }
    counter2++;
    total_answer = (total_answer + ((counter2 - current) % MOD1 + MOD1) % MOD1) % MOD2;
    for (int d = (level == 0 ? 1 : 0); d <= 9; ++d) {
        search(level + 1, current * 10 + d);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> limit;
    generate(0, 0);
    for (int i = 0; i <= 6; ++i) {
        sort(digit_vectors[i].begin(), digit_vectors[i].end());
    }
    counter2 = -1;
    search(0, 0);
    cout << total_answer << '\n';
    return 0;
}
